#include "mspa/semantics/registry.hpp"
#include <algorithm>
#include <cmath>
#include <set>
namespace mspa {
RegistrySnapshot::RegistrySnapshot():data_(std::make_shared<const RegistryData>()){}
RegistrySnapshot::RegistrySnapshot(std::shared_ptr<const RegistryData>d):data_(d?std::move(d):std::make_shared<const RegistryData>()){}
const RegistryData& RegistrySnapshot::data()const noexcept{return *data_;}
const PredicateSchema* RegistrySnapshot::find(PredicateId id)const noexcept{auto it=data_->predicates.find(id);return it==data_->predicates.end()?nullptr:&it->second;}
const ActionSchema* RegistrySnapshot::find_action(ActionTypeId id)const noexcept{auto it=data_->action_schemas.find(id);return it==data_->action_schemas.end()?nullptr:&it->second;}
const ConsiderationSchema* RegistrySnapshot::find_consideration(const std::string&id)const noexcept{auto it=data_->considerations.find(id);return it==data_->considerations.end()?nullptr:&it->second;}
RegistryBuilder::RegistryBuilder()=default; RegistryBuilder::RegistryBuilder(const RegistrySnapshot&b):data_(b.data()){}
Result<void> RegistryBuilder::add_predicate(PredicateSchema s){if(!s.id.valid()||!s.name_space.valid())return make_error(ErrorCode::InvalidArgument,"invalid predicate schema"); if(data_.predicates.count(s.id))return make_error(ErrorCode::NamespaceConflict,"predicate already registered"); std::set<std::string> roles; for(const auto&r:s.required_roles){if(r.empty()||!roles.insert(r).second)return make_error(ErrorCode::InvalidArgument,"invalid/duplicate required role");} for(const auto&r:s.optional_roles){if(r.empty()||!roles.insert(r).second)return make_error(ErrorCode::InvalidArgument,"duplicate role");} s.default_relevance=std::clamp(s.default_relevance,0.0f,1.0f);s.default_consequence=std::clamp(s.default_consequence,-1.0f,1.0f);s.intentionality=std::clamp(s.intentionality,0.0f,1.0f);data_.predicates.emplace(s.id,std::move(s));return {};}
Result<void> RegistryBuilder::add_concept(ConceptId id,std::string n){if(!id.valid()||n.empty())return make_error(ErrorCode::InvalidArgument,"invalid concept");if(data_.concepts.count(id))return make_error(ErrorCode::NamespaceConflict,"concept already registered");data_.concepts.emplace(id,std::move(n));return {};}
Result<void> RegistryBuilder::add_action_type(ActionTypeId id,std::string n){if(!id.valid()||n.empty())return make_error(ErrorCode::InvalidArgument,"invalid action type");if(data_.action_types.count(id))return make_error(ErrorCode::NamespaceConflict,"action type already registered");data_.action_types.emplace(id,std::move(n));return {};}
Result<void> RegistryBuilder::add_action_schema(ActionSchema s){if(!s.id.valid()||!s.name_space.valid())return make_error(ErrorCode::InvalidArgument,"invalid action schema");if(data_.action_schemas.count(s.id))return make_error(ErrorCode::NamespaceConflict,"action schema already registered");for(const auto&id:s.considerations)if(!data_.considerations.count(id))return make_error(ErrorCode::InvalidArgument,"action schema references unknown consideration: "+id);data_.action_schemas.emplace(s.id,std::move(s));return {};}
Result<void> RegistryBuilder::add_consideration(ConsiderationSchema s){if(s.id.empty()||!std::isfinite(s.weight))return make_error(ErrorCode::InvalidArgument,"invalid consideration");if(data_.considerations.count(s.id))return make_error(ErrorCode::NamespaceConflict,"consideration already registered");float prev=-3.402823466e38F;for(const auto&p:s.curve){if(!std::isfinite(p.x)||!std::isfinite(p.y)||p.x<prev)return make_error(ErrorCode::InvalidArgument,"invalid consideration curve");prev=p.x;}data_.considerations.emplace(s.id,std::move(s));return {};}
Result<void> RegistryBuilder::add_inference_rule(InferenceRuleData r){if(!r.id||!r.conclusion.valid())return make_error(ErrorCode::InvalidArgument,"invalid inference rule");if(std::any_of(data_.inference_rules.begin(),data_.inference_rules.end(),[&](const auto&x){return x.id==r.id;}))return make_error(ErrorCode::NamespaceConflict,"inference rule id already registered");r.base_certainty=std::clamp(r.base_certainty,0.0f,1.0f);data_.inference_rules.push_back(std::move(r));return {};}
Result<void> RegistryBuilder::add_default_value(ConceptId id,float intensity){if(!id.valid()||!std::isfinite(intensity)||intensity<0.0f||intensity>1.0f)return make_error(ErrorCode::InvalidArgument,"invalid default value");data_.default_values[id]=intensity;return {};}
Result<void> RegistryBuilder::mark_pack(PackId id,std::uint32_t major,std::uint32_t minor,std::uint32_t patch){if(!id.valid())return make_error(ErrorCode::InvalidArgument,"invalid pack id");auto it=std::find_if(data_.loaded_packs.begin(),data_.loaded_packs.end(),[&](const LoadedPackInfo&x){return x.id==id;});if(it!=data_.loaded_packs.end()){if(it->version_major!=major||it->version_minor!=minor||it->version_patch!=patch)return make_error(ErrorCode::NamespaceConflict,"pack id already loaded with a different version");return {};}data_.loaded_packs.push_back({id,major,minor,patch});return {};}
bool RegistryBuilder::contains_pack(PackId id)const noexcept{return pack_info(id)!=nullptr;}
bool RegistryBuilder::contains_pack(PackId id,std::uint32_t min_major,std::uint32_t min_minor)const noexcept{const auto*p=pack_info(id);if(!p)return false;if(p->version_major!=min_major)return p->version_major>min_major;return p->version_minor>=min_minor;}
const LoadedPackInfo* RegistryBuilder::pack_info(PackId id)const noexcept{auto it=std::find_if(data_.loaded_packs.begin(),data_.loaded_packs.end(),[&](const LoadedPackInfo&x){return x.id==id;});return it==data_.loaded_packs.end()?nullptr:&*it;}
const RegistryData& RegistryBuilder::data()const noexcept{return data_;}
RegistrySnapshot RegistryBuilder::publish()const{return RegistrySnapshot(std::make_shared<const RegistryData>(data_));}
Result<void> validate_proposition(const Proposition&p,const RegistrySnapshot&r,std::size_t max_args,std::size_t max_str){if(!p.predicate.valid()||!p.name_space.valid())return make_error(ErrorCode::InvalidArgument,"proposition requires predicate and namespace");if(p.arguments.size()>max_args)return make_error(ErrorCode::QuotaExceeded,"too many proposition arguments");const auto*s=r.find(p.predicate);if(s&&s->name_space!=p.name_space)return make_error(ErrorCode::NamespaceConflict,"predicate namespace mismatch");std::set<std::string> roles;for(const auto&a:p.arguments){if(a.role.empty()||a.role.size()>max_str||a.value.size()>max_str)return make_error(ErrorCode::InvalidArgument,"invalid proposition argument");if(!roles.insert(a.role).second)return make_error(ErrorCode::InvalidArgument,"duplicate proposition role");}if(s){for(const auto&role:s->required_roles)if(!find_argument(p,role))return make_error(ErrorCode::InvalidArgument,"missing required proposition role: "+role);}return {};}
} // namespace mspa
